export function evaluate({ inputs, time }) {
  const launchSpeed = inputs.launchSpeed;
  const gravity = inputs.gravity;
  const mass = inputs.mass;

  const apexTime = launchSpeed / gravity;
  const apexHeight = (launchSpeed * launchSpeed) / (2 * gravity);
  const height = launchSpeed * time - 0.5 * gravity * time * time;
  const velocity = launchSpeed - gravity * time;
  const acceleration = -gravity;
  const force = mass * gravity;

  let motionState = "Rising";
  if (time <= 0.001) {
    motionState = "Ready to toss";
  } else if (Math.abs(velocity) < 0.05) {
    motionState = "At the top";
  } else if (velocity < 0) {
    motionState = height <= 0 ? "Back at launch height" : "Falling";
  }

  const objects = [];

  objects.push(...sdk.panel({
    id: "lane.motion",
    x: 30,
    y: 30,
    w: 280,
    h: 340,
    title: "Motion & Forces",
    state: motionState
  }));

  objects.push(sdk.axis("axis.height", {
    x: 80,
    y: 70,
    length: 260,
    orientation: "y",
    min: 0,
    max: 2.2,
    ticks: [0, 0.5, 1.0, 1.5, 2.0],
    label: "Height",
    unit: "m"
  }));

  const ballY = 330 - (height / 2.2) * 260;
  objects.push(sdk.circle("ball.toss", 180, ballY, 24, { role: "output" }));

  objects.push(...sdk.vector("vec.v", { x: 210, y: ballY }, { value: velocity, direction: "up" }, { scale: 15, label: "v", role: "output" }));
  objects.push(...sdk.vector("vec.a", { x: 235, y: ballY }, { value: acceleration, direction: "up" }, { scale: 15, label: "a", role: "prediction" }));

  objects.push(...sdk.callout(250, ballY - 30, [
    `v: ${sdk.format(velocity)} m/s`,
    `a: ${sdk.format(acceleration)} m/s^2`,
    `Fg: ${sdk.format(force)} N`
  ], { id: "callout.toss" }));

  const points = sdk.sample((t) => launchSpeed - gravity * t, 0, Math.max(1.6666666666666667, time), 20);
  const currentPoints = points.filter(p => p[0] <= time);

  objects.push(sdk.plot("plot.vt", {
    x: 330,
    y: 30,
    w: 280,
    h: 340,
    axes: {
      x: { label: "Time", min: 0, max: 1.8, unit: "s" },
      y: { label: "Velocity", min: -5.5, max: 5.5, unit: "m/s" }
    },
    series: [
      {
        label: "v(t)",
        kind: "line",
        points: currentPoints.map(p => ({ x: p[0], y: p[1] }))
      }
    ],
    marker: {
      x: time,
      y: velocity,
      label: "t"
    }
  }));

  objects.push(sdk.text("plot.vt.note", 340, 390, "Slope a = -g", { role: "muted" }));

  return {
    frame: {
      width: 640,
      height: 420,
      objects,
      readouts: [
        { id: "velocity", value: velocity },
        { id: "acceleration", value: acceleration },
        { id: "force", value: force },
        { id: "motionState", value: motionState }
      ]
    },
    quantities: {
      launchSpeed,
      gravity,
      mass,
      apexTime,
      apexHeight,
      height,
      velocity,
      acceleration,
      force
    }
  };
}
